import{_ as s,o as e,c as l,ag as a}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"Skill 生效原理","description":"","frontmatter":{},"headers":[],"relativePath":"AI/skill-how.md","filePath":"AI/skill-how.md"}'),i={name:"AI/skill-how.md"};function o(d,t,n,r,c,h){return e(),l("div",null,[...t[0]||(t[0]=[a(`<h1 id="skill-生效原理" tabindex="-1">Skill 生效原理 <a class="header-anchor" href="#skill-生效原理" aria-label="Permalink to &quot;Skill 生效原理&quot;">​</a></h1><p>Skill <strong>不是插件，也没有独立进程</strong>。磁盘上多一个 <code>SKILL.md</code>，并不会自动跑脚本、也不会每条消息都塞进模型。</p><p>真正生效靠三件事串起来：</p><ol><li><strong>被扫描到</strong>：Host（Cursor、Claude Code 等）启动时扫描约定目录</li><li><strong>被选中</strong>：模型根据 <code>description</code>（或你手动 <code>/技能名</code>）判断「现在该用这个」</li><li><strong>被读进上下文</strong>：Agent 用读文件 / 跑命令的方式把正文加载进来，再当执行协议去跟</li></ol><p>概念与怎么写见：<a href="./skill.html">Skill 说明</a>、<a href="./create-skill.html">如何编写 Skill</a>。文件是怎么落到这些目录的，见：<a href="./skill-install.html">npx skills 怎么安装</a>。</p><h2 id="三级渐进披露" tabindex="-1">三级渐进披露 <a class="header-anchor" href="#三级渐进披露" aria-label="Permalink to &quot;三级渐进披露&quot;">​</a></h2><p>这套加载策略叫 <strong>渐进披露（Progressive Disclosure）</strong>：上下文里先只放目录，真正相关时才翻开章节，需要附录时再翻附录。这样可以装很多 Skill，而不把窗口一次性撑爆。</p><table tabindex="0"><thead><tr><th>级别</th><th>何时进入上下文</th><th>装什么</th></tr></thead><tbody><tr><td><strong>L1 元数据</strong></td><td>会话启动，几乎始终在</td><td>只把 <code>name</code> + <code>description</code> 放进系统提示（每个大约一百来个 token）</td></tr><tr><td><strong>L2 指令正文</strong></td><td>意图对上，或你打了 <code>/技能名</code></td><td>才去读完整 <code>SKILL.md</code></td></tr><tr><td><strong>L3 附属资源</strong></td><td>正文里点名需要时</td><td>再打开 <code>references/</code>，或去跑 <code>scripts/</code>（脚本只带回运行输出）</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[会话启动] --&gt; B[扫描 Skills 目录]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[&quot;L1：只注入 name + description&lt;br/&gt;约 100 token / 个&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[用户发消息]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E{description 匹配&lt;br/&gt;或用户打了 /技能名?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt;|否| F[当普通任务处理]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt;|是| G[L2：读取完整 SKILL.md 正文]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  G --&gt; H[按步骤执行]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  H --&gt; I{还要参考资料或脚本?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  I --&gt;|读文件| J[L3：按需打开 references]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  I --&gt;|跑命令| K[L3：执行 scripts，只把输出带回]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  I --&gt;|否| L[按约定产出结果]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  J --&gt; L</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  K --&gt; L</span></span></code></pre></div><p>由此直接推出三条写作约束：</p><ul><li><strong><code>description</code> 决定会不会被用上。</strong> L1 里模型只看得见这一句。写糊了，等于这个 Skill 对 Agent 不存在。写法见：<a href="./create-skill.html#写好-description决定能不能被用上">如何编写 Skill</a></li><li><strong>正文太长会拖累每一次触发。</strong> 长规范、大表、完整 API 放到 <code>references/</code>，主文件只链一层</li><li><strong>脚本是「手脚」，不是「自动挂载」。</strong> Agent 按正文去终端执行，带回的是运行输出，不是把整份脚本贴进 prompt</li></ul><p>官方说明可对照：<a href="https://agentskills.io" target="_blank" rel="noreferrer">Agent Skills 规范</a>、<a href="https://www.anthropic.com/engineering/equipping-agents-for-the-real-world-with-agent-skills" target="_blank" rel="noreferrer">Anthropic：Equipping agents with Agent Skills</a>、<a href="https://cursor.com/docs/skills" target="_blank" rel="noreferrer">Cursor Skills</a>。</p><h2 id="从哪被扫描到" tabindex="-1">从哪被扫描到 <a class="header-anchor" href="#从哪被扫描到" aria-label="Permalink to &quot;从哪被扫描到&quot;">​</a></h2><p>Host 会递归查找「目录 + <code>SKILL.md</code>」。常见位置：</p><table tabindex="0"><thead><tr><th>范围</th><th>典型目录</th></tr></thead><tbody><tr><td>项目内（跟仓库走）</td><td><code>.cursor/skills/</code>、<code>.agents/skills/</code>、<code>.claude/skills/</code></td></tr><tr><td>本机全局</td><td><code>~/.cursor/skills/</code>、<code>~/.agents/skills/</code>、<code>~/.claude/skills/</code></td></tr></tbody></table><p>兼容层因产品而异：Cursor 还会扫 <code>.codex/skills/</code>；Claude Code 以 <code>.claude/skills/</code> 为主。<strong>身份来自包含 <code>SKILL.md</code> 的那一层文件夹名</strong>，外层分类目录只是整理用。</p><p>Monorepo 里也可以把 Skill 放在子包旁（如 <code>apps/web/.cursor/skills/</code>），部分 Host 会把它自动限定在该子树相关的文件上。从 GitHub 一键写入这些目录，见：<a href="./skill-install.html">npx skills 怎么安装</a>。</p><h2 id="两种触发方式" tabindex="-1">两种触发方式 <a class="header-anchor" href="#两种触发方式" aria-label="Permalink to &quot;两种触发方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>谁决定用</th><th>典型动作</th></tr></thead><tbody><tr><td><strong>自动匹配</strong></td><td>Agent 拿用户意图去对 <code>description</code></td><td>你说「帮我做代码评审」，它自己去读评审 Skill</td></tr><tr><td><strong>显式调用</strong></td><td>你点名</td><td>输入 <code>/技能名</code>，或用 <code>@</code> 把 Skill 贴进当前消息</td></tr></tbody></table><p>可调开关（字段名以 Cursor / Agent Skills 实践为准，其他 Host 可能略有差异）：</p><ul><li><code>disable-model-invocation: true</code>：关掉自动匹配，只在你打 <code>/技能名</code> 时进入上下文（行为接近以前的 Slash Command）</li><li><code>paths</code>：按 glob 限制「正在处理哪些文件时才露出这个 Skill」，避免无关任务也被匹配上</li></ul><p>显式调用通常只作用于<strong>当前这一条消息</strong>。若要整段会话都带着同一套协议，需要 Host 提供的「自定义模式 / Custom Mode」一类能力，而不是指望 Skill 自己常驻。</p><h2 id="和-rules-差在哪-所以「写了不等于生效」" tabindex="-1">和 Rules 差在哪（所以「写了不等于生效」） <a class="header-anchor" href="#和-rules-差在哪-所以「写了不等于生效」" aria-label="Permalink to &quot;和 Rules 差在哪（所以「写了不等于生效」）&quot;">​</a></h2><p>完整对照见：<a href="./skill-vs-mcp.html">Skill、MCP、Rule 异同</a>，Rule 写法见：<a href="./rule.html">Rule</a>。</p><table tabindex="0"><thead><tr><th></th><th>Rules（规则）</th><th>Skill</th></tr></thead><tbody><tr><td><strong>进上下文的方式</strong></td><td>常驻或按 glob 自动注入全文</td><td>先只放目录（L1），匹配后再读正文（L2）</td></tr><tr><td><strong>适合什么</strong></td><td>短约束、始终要遵守的规范</td><td>按场景启用的流程、清单、脚本</td></tr><tr><td><strong>写长了会怎样</strong></td><td>每条消息都占窗口</td><td>未触发时几乎不占窗口</td></tr></tbody></table><p>所以：把 200 行排障手册塞进 <code>alwaysApply</code> 的 Rule，和做成 Skill，成本完全不同。Skill 能装得多、写得细，前提是 <strong>L1 的 <code>description</code> 足够让模型「想起来去打开它」</strong>。</p><p>用户的明确指令（对话里的要求、<a href="./agents-md.html">AGENTS.md</a> / <code>CLAUDE.md</code> 等）优先级通常高于 Skill。Skill 和用户指令打架时，以用户为准——这也是「没生效」的一种常见原因。完整对照见：<a href="./skill-vs-mcp.html">Skill、MCP、Rule 异同</a>；Rule 怎么写见：<a href="./rule.html">Rule</a>。</p><h2 id="写了却没生效-先查这几项" tabindex="-1">写了却没生效，先查这几项 <a class="header-anchor" href="#写了却没生效-先查这几项" aria-label="Permalink to &quot;写了却没生效，先查这几项&quot;">​</a></h2><ol><li><strong>目录不对或没有 <code>SKILL.md</code></strong>：没被扫描到，L1 都进不去</li><li><strong><code>description</code> 没有触发词</strong>：用户说的是「超时 / 白屏」，描述里却只写了「帮助处理问题」</li><li><strong>开了 <code>disable-model-invocation</code></strong>：必须手动 <code>/技能名</code>，等自动匹配会一直等不到</li><li><strong><code>paths</code> 太窄</strong>：当前打开的文件对不上 glob，Skill 根本不会出现在候选里</li><li><strong>正文与更高优先级指令冲突</strong>：用户说「先别跑测试」，Skill 里写「必须先跑测试」→ 以用户为准</li><li><strong>以为脚本会自动执行</strong>：没有。Agent 只有在读到正文、并且决定执行那一步时，才会去跑 <code>scripts/</code></li></ol>`,29)])])}const k=s(i,[["render",o]]);export{g as __pageData,k as default};
